const q = ($input.first().json.query || {});
const t = String(q.t || '');
if (!/^[A-Za-z0-9]{16,64}$/.test(t)) return [{ json: { gueltig: false, status: 'ungueltig' } }];
return [{ json: { gueltig: true, t } }];

const parse = (s) => { if (!s) return null; const d = new Date(String(s).replace(' ', 'T')); return isNaN(d) ? null : d; };
const ymd = (d) => d.toLocaleDateString('en-CA', { timeZone: 'Europe/Berlin' });
const hourBerlin = (d) => parseInt(new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Berlin', hour: '2-digit', hourCycle: 'h23' }).format(d), 10);
const fmtDe = (d) => d ? d.toLocaleDateString('de-DE', { timeZone: 'Europe/Berlin', day: '2-digit', month: '2-digit', year: 'numeric' }) : '';
// Beginn des Folgetags (Berlin) nach dem Berlin-Tag von d = Ende des Anmeldeschluss-Tages
const nextMidnight = (d) => {
  const [y, m, dd] = ymd(d).split('-').map(Number);
  const n = new Date(Date.UTC(y, m - 1, dd + 1));
  const target = n.toISOString().slice(0, 10);
  for (const off of [1, 2]) {
    const t = new Date(n.getTime() - off * 3600000);
    if (ymd(t) === target && hourBerlin(t) === 0) return t;
  }
  return new Date(n.getTime() - 3600000);
};

const res = $input.first().json;
const b = (res.items || [])[0];
const hin = (status) => [{ json: { zahlbar: false, status } }];
if (!b) return hin('ungueltig');
if (b.status === 'bezahlt') return hin('bezahlt');
if (b.status !== 'offen') return hin('verfallen');
const tn = b.expand && b.expand.teilnehmer;
const ev = tn && tn.expand && tn.expand.event;
if (!tn || !ev) return hin('ungueltig');
if (tn.status !== 'offen') return hin(tn.status === 'aktiv' ? 'bezahlt' : 'verfallen');
const schluss = parse(ev.anmeldeschluss);
if (schluss && Date.now() >= nextMidnight(schluss).getTime()) return hin('verfallen');
const items = (Array.isArray(b.line_items) ? b.line_items : []).map((i) => ({
  bezeichnung: i.typ === 'versand_ch' ? 'Versandaufschlag Schweiz' : (ev.name + ' – Startgebühr'),
  betrag_cent: i.betrag_cent
}));
if (!items.length) return hin('ungueltig');
return [{ json: { zahlbar: true, bestellung_id: b.id, teilnehmer_id: tn.id,
  email: tn.kategorie === 'kind' ? (tn.eltern_email || tn.email || '') : (tn.email || ''),
  waehrung: String(ev.waehrung || 'EUR').toLowerCase(), items } }];

const c = $input.first().json;
const parts = [];
const p = { set: (k, v) => parts.push(encodeURIComponent(k) + '=' + encodeURIComponent(String(v))) };
p.set('mode', 'payment');
p.set('locale', 'de');
if (c.email) p.set('customer_email', c.email);
p.set('success_url', 'https://runrebels.com/danke.html');
p.set('cancel_url', 'https://runrebels.com/zahlung.html?status=abgebrochen');
p.set('metadata[bestellung_id]', c.bestellung_id);
p.set('metadata[teilnehmer_id]', c.teilnehmer_id);
p.set('payment_intent_data[metadata][bestellung_id]', c.bestellung_id);
p.set('payment_intent_data[metadata][teilnehmer_id]', c.teilnehmer_id);
c.items.forEach((it, i) => {
  p.set('line_items[' + i + '][quantity]', '1');
  p.set('line_items[' + i + '][price_data][currency]', c.waehrung);
  p.set('line_items[' + i + '][price_data][unit_amount]', String(it.betrag_cent));
  p.set('line_items[' + i + '][price_data][product_data][name]', it.bezeichnung);
});
return [{ json: { body: parts.join('&') } }];
